/*
 * ChatWindow.jsx — Right panel: conversation header, messages, and input.
 */

import { useEffect, useRef } from 'react';
import './ChatWindow.css';

export default function ChatWindow({
  user,
  messages,
  draft,
  onDraftChange,
  onSend,
  loading = false,
  sendingMessage = false,
  onRetryMessage = null,
}) {
  const bottomRef = useRef(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleKeyDown = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      onSend();
    }
  };

  if (!user) {
    return (
      <div className="chat-window chat-window--empty">
        <p className="chat-window__empty-text">اختر محادثة لبدء الدردشة</p>
      </div>
    );
  }

  return (
    <div className="chat-window">
      <header className="chat-window__header">
        <div className="chat-window__avatar">{user.initials}</div>
        <div className="chat-window__header-info">
          <h3 className="chat-window__name">{user.name}</h3>
          <span className="chat-window__status">
            {user.online ? 'متصل' : 'غير متصل'}
          </span>
        </div>
      </header>

      <div className="chat-window__messages">
        {loading ? (
          <div className="chat-window__loading">
            جاري التحميل...
          </div>
        ) : (
          messages.map(msg => (
            <div
              key={msg.id}
              className={`chat-window__bubble-wrap chat-window__bubble-wrap--${msg.sender}`}
            >
              <div className={`chat-window__bubble chat-window__bubble--${msg.sender} ${msg.failed ? 'chat-window__bubble--failed' : ''}`}>
                <p className="chat-window__text">{msg.text}</p>
                <span className="chat-window__msg-time">{msg.time}</span>
              </div>
              {msg.failed && onRetryMessage && (
                <button
                  className="chat-window__message-retry-btn"
                  onClick={() => onRetryMessage(msg)}
                  title="إعادة محاولة الإرسال"
                  type="button"
                >
                  ❌
                </button>
              )}
            </div>
          ))
        )}
        <div ref={bottomRef} />
      </div>

      <footer className="chat-window__footer">
        <textarea
          className="chat-window__input"
          placeholder="اكتب رسالة..."
          rows={1}
          value={draft}
          onChange={e => onDraftChange(e.target.value)}
          onKeyDown={handleKeyDown}
        />
        <button
          type="button"
          className="chat-window__send-btn"
          onClick={onSend}
          disabled={!draft.trim() || sendingMessage}
          aria-label="إرسال رسالة"
          title={sendingMessage ? 'جاري الإرسال...' : 'إرسال'}
        >
          {sendingMessage ? (
            <span className="chat-window__send-loader">⏳</span>
          ) : (
            <svg viewBox="0 0 24 24" fill="currentColor">
              <path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z" />
            </svg>
          )}
        </button>
      </footer>
    </div>
  );
}
